using Microsoft.AspNetCore.Mvc; using Microsoft.AspNetCore.Mvc.RazorPages; using Microsoft.EntityFrameworkCore; using MYOB.Data; using MYOB.Models; using MYOB.Services; using MYOB.Support;
namespace MYOB.Pages.Settings.Materials;
public class IndexModel(ApplicationDbContext db, IPermissionService permissions) : PageModel
{
    public IReadOnlyList<Material> Items {get;private set;}=[]; [BindProperty(SupportsGet=true)] public string? Search{get;set;} [BindProperty(SupportsGet=true)] public int PageNumber{get;set;}=1; public int TotalPages{get;private set;} public bool CanAdd{get;private set;} public bool CanUpdate{get;private set;} public bool CanDelete{get;private set;}
    public async Task OnGetAsync(){const int size=15;PageNumber=Math.Max(1,PageNumber);var q=db.Materials.Include(x=>x.UnitOfMeasure).AsNoTracking();if(!string.IsNullOrWhiteSpace(Search))q=q.Where(x=>x.Name.Contains(Search)||x.UnitOfMeasure.Name.Contains(Search));var count=await q.CountAsync();TotalPages=Math.Max(1,(int)Math.Ceiling(count/(double)size));PageNumber=Math.Min(PageNumber,TotalPages);Items=await q.OrderBy(x=>x.Name).Skip((PageNumber-1)*size).Take(size).ToListAsync();CanAdd=await permissions.HasAsync(User,ScreenCatalog.Materials,PermissionAction.Add);CanUpdate=await permissions.HasAsync(User,ScreenCatalog.Materials,PermissionAction.Update);CanDelete=await permissions.HasAsync(User,ScreenCatalog.Materials,PermissionAction.Delete);}
    public async Task<IActionResult> OnPostDeleteAsync(Guid id){if(!await permissions.HasAsync(User,ScreenCatalog.Materials,PermissionAction.Delete))return Forbid();var item=await db.Materials.SingleOrDefaultAsync(x=>x.Id==id);if(item is null)return NotFound();if(await db.SupplierReceipts.AnyAsync(x=>x.MaterialId==id)){TempData["Error"]="لا يمكن حذف خامة مرتبطة بحركات.";return RedirectToPage();}item.IsDeleted=true;item.DeletedAt=DateTimeOffset.UtcNow;item.DeletedBy=User.Identity?.Name;await db.SaveChangesAsync();TempData["Message"]="تم حذف الخامة";return RedirectToPage();}
}
